/* ═══════════════════════════════════════════════════════════════════
   CITY SOCCER CLUB — ALMANCA SÖZLÜK  (de)

   Anahtar = oyunda geçen Türkçe metnin BİREBİR kendisi.
   Burada olmayan her şey (oyuncu adı, takım adı, sohbet) olduğu gibi kalır.

   Bu dosya index.html tarafından, YALNIZCA dil Almanca ise indirilir.

   Güncelleme yaparken: index.html içindeki _i18nSozlukSurum değerini de
   artır, yoksa tarayıcı eski kopyayı kullanmaya devam eder.
   ═══════════════════════════════════════════════════════════════════ */
window.I18N = window.I18N || {};
window.I18N.de = window.I18N.de || {};
window.I18N_PATTERNS = window.I18N_PATTERNS || {};
window.I18N_PATTERNS.de = window.I18N_PATTERNS.de || [];

/* Desen içindeki alt metni çevirmek için: önce sözlük, sonra tam T(). */
window._i18nIcCevirDe = function (t) {
  if (window.I18N && window.I18N.de && window.I18N.de[t] != null) return window.I18N.de[t];
  try { if (typeof window.T === 'function') { var r = window.T(t); if (r != null) return r; } } catch (e) {}
  return t;
};
var _icD = window._i18nIcCevirDe;

/* Almanca sıra sayısı: 1 → "1.", lig adları için */
var _DE_LIG = ['', '2. Liga', '3. Liga', '4. Liga', '5. Liga', '6. Liga', '7. Liga', '8. Liga'];

/* ── Çekirdek desenler (index.html'den taşınan 50 desen) ───────────── */
window.I18N_PATTERNS.de.push(
  [/^Gün (\d+)$/,                         'Tag $1'],
  [/^Gün (\d+) \/ (\d+)$/,                'Tag $1 / $2'],
  [/^Sezon (\d+)$/,                       'Saison $1'],
  [/^Sezon (\d+)'de başlar$/,             'Beginnt in Saison $1'],
  [/^Hafta (\d+)$/,                       'Woche $1'],
  [/^(\d+)\. Hafta$/,                     'Woche $1'],
  [/^(\d+)\. Lig$/,                       m => _DE_LIG[Number(m[1])] || (m[1] + '. Liga')],
  [/^(\d+)\. Lig (\d+)\. Hafta$/,         m => (_DE_LIG[Number(m[1])] || (m[1] + '. Liga')) + ' · Woche ' + m[2]],
  [/^Seri: (\d+)\/7 gün$/,                'Serie: $1/7 Tage'],
  [/^Gün (\d+) Hediyen Hazır$/,           'Geschenk für Tag $1 bereit'],
  [/^(\d+) gün$/,                         '$1 Tage'],
  [/^(\d+) maç$/,                         '$1 Spiele'],
  [/^(\d+) gol$/,                         '$1 Tore'],
  [/^(\d+) asist$/,                       '$1 Vorlagen'],
  [/^Cezalı \((\d+) maç\)$/,              'Gesperrt ($1 Spiele)'],
  [/^Sakat — (\d+)s iyileşme$/,           'Verletzt — $1 Std. Heilung'],
  [/^Kademe (\d+)$/,                      'Stufe $1'],
  [/^Grup (\d+)\. Maç$/,                  'Gruppenspieltag $1'],
  [/^Son (\d+) - (\d+)\. Maç$/,           'Runde der letzten $1 – Spiel $2'],
  [/^(\d+)\. maç$/,                       'Spiel $1'],
  [/^(\d+) takım · (\d+) maç$/,           '$1 Teams · $2 Spiele'],
  [/^(.+?) \+(\d+)%$/,                    m => _icD(m[1]) + ' +' + m[2] + '%'],
  [/^(.+?) cezası$/,                      m => _icD(m[1]) + '-Sperre']
);

window.I18N_PATTERNS.de.push(
  [/^Cezalı \(\$\{_susp\} maç\)$/,        'Gesperrt (${_susp} Spiele)'],
  [/^Yarın ·$/,                           'Morgen ·'],
  [/^(\d+) kişi$/,                        '$1 Personen'],
  [/^(\d+)\. sıra$/,                      'Platz $1'],
  [/^(\d+)\. Maç$/,                       'Spieltag $1'],
  [/^(\d+) maça çık$/,                    'Bestreite $1 Spiele'],
  [/^(\d+) kez maçın adamı ol$/,          'Werde $1-mal Spieler des Spiels'],
  [/^(\d+) kez takıma katıl$/,            'Tritt $1-mal einem Team bei'],
  [/^%(\d+) hazır$/,                      '$1 % bereit'],
  [/^\+%(\d+) hücum, \+%(\d+) savunma$/,  '+$1 % Angriff, +$2 % Abwehr'],
  [/^(\d+) takım · (\d+) maç$/,           '$1 Teams · $2 Spiele'],
  [/^(\d+)\/(\d+) gün$/,                  '$1/$2 Tage']
);

window.I18N_PATTERNS.de.push(
  [/^(.+?) · Hafta (\d+)$/,   m => _icD(m[1]) + ' · Woche ' + m[2]],
  [/^· Gün (\d+)$/,           '· Tag $1'],
  [/^Gün (\d+) ·$/,           'Tag $1 ·'],
  [/^Sezon (\d+) görev süresi$/, 'Aufgabenzeitraum Saison $1'],
  [/^(\d+)\.,\s*(\d+)\.,\s*(\d+)\. ve (\d+)\. günleri$/, 'Tage $1, $2, $3 und $4'],
  [/^Son (\d+) Maç$/,         'Letzte $1 Spiele'],
  [/^Son (\d+) maç$/,         'letzte $1 Spiele'],
  [/^(\d+) farklı rol$/,      '$1 verschiedene Rollen'],
  [/^(\d+) kişi · Başkan tarafından atandı$/, '$1 Personen · vom Präsidenten ernannt']
);

window.I18N_PATTERNS.de.push(
  [/^(Pazartesi|Salı|Çarşamba|Perşembe|Cuma|Cumartesi|Pazar), (\d{1,2}) (Ocak|Şubat|Mart|Nisan|Mayıs|Haziran|Temmuz|Ağustos|Eylül|Ekim|Kasım|Aralık) (\d{4})$/,
    m => _icD(m[1]) + ', ' + m[2] + '. ' + _icD(m[3]) + ' ' + m[4]],
  [/^(\d{1,2}) (Ocak|Şubat|Mart|Nisan|Mayıs|Haziran|Temmuz|Ağustos|Eylül|Ekim|Kasım|Aralık) (\d{4})$/,
    m => m[1] + '. ' + _icD(m[2]) + ' ' + m[3]],
  [/^⚽ Maç tamamlandı · (.+)$/, '⚽ Spiel beendet · $1'],
  [/^Sv\. (\d+)$/,               'Lv. $1'],
  [/^Sezon (\d+) sona erdi$/,    'Saison $1 ist beendet'],
  [/^(\d+)\. denemede yüklendi$/, 'beim $1. Versuch geladen']
);

