/* ══ DESENLER · 12. küme · genel tarih düğümü çevirici + yardımcı ══ */
window._i18nEsAdDe = function (s) {
  try {
    var m = String(s).match(/^([^A-Za-zÇĞİÖŞÜçğıöşü]*)([\s\S]*?)([^A-Za-zÇĞİÖŞÜçğıöşü]*)$/);
    if (!m || !m[2]) return s;
    return m[1] + _icD(m[2]) + m[3];
  } catch (e) { return s; }
};
var _esAdDe = window._i18nEsAdDe;

(function () {
  var GUN = {
    'Pazartesi':'Montag','Salı':'Dienstag','Çarşamba':'Mittwoch','Perşembe':'Donnerstag',
    'Cuma':'Freitag','Cumartesi':'Samstag','Pazar':'Sonntag',
    'Pzt':'Mo','Sal':'Di','Çar':'Mi','Per':'Do','Cum':'Fr','Cmt':'Sa','Paz':'So','Pzr':'So'
  };
  var AY = {
    'Ocak':'Januar','Şubat':'Februar','Mart':'März','Nisan':'April','Mayıs':'Mai','Haziran':'Juni',
    'Temmuz':'Juli','Ağustos':'August','Eylül':'September','Ekim':'Oktober','Kasım':'November','Aralık':'Dezember',
    'Oca':'Jan','Şub':'Feb','Mar':'Mär','Nis':'Apr','May':'Mai','Haz':'Jun',
    'Tem':'Jul','Ağu':'Aug','Eyl':'Sep','Eki':'Okt','Kas':'Nov','Ara':'Dez'
  };
  var OZEL = { 'Bugün':'Heute','Dün':'Gestern','Yarın':'Morgen','Saat':'Uhrzeit','Gün':'Tag','Sezon':'Saison' };
  var HARITA = {};
  [GUN, AY, OZEL].forEach(function (o) { for (var k in o) HARITA[k] = o[k]; });
  var ANAHTARLAR = Object.keys(HARITA).sort(function (a, b) { return b.length - a.length; });
  var PARCA = new RegExp('(' + ANAHTARLAR.join('|') + ')', 'g');
  var SINIR = '[^A-Za-zÇĞİÖŞÜçğıöşü]*';
  var TARIH_RE = new RegExp('^' + SINIR + '(?:(?:' + ANAHTARLAR.join('|') + ')' + SINIR + ')+$');
  window.I18N_PATTERNS.de.push(
    [TARIH_RE, function (m) {
      // Almanca: gün numarasından sonra nokta gelir → "12. September 2026"
      return m[0].replace(PARCA, function (t) { return HARITA[t]; })
        .replace(/(^|[\s·|(])(\d{1,2}) (Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember|Jan|Feb|Mär|Apr|Jun|Jul|Aug|Sep|Okt|Nov|Dez)(?=$|[\s·|),])/g, '$1$2. $3');
    }]
  );
})();

